package upstream

import "strings"

// SingBoxPinnedVersion is the release we ship/cache/install by default (no "v" prefix).
//
// Pin rationale (2026-11): 1.12.22 — DNS server format type+server required;
// configs generated by netductor use 1.12-era DNS. Do not jump to 1.14 until
// secondary/primary/client DNS helpers are verified on canary.
const SingBoxPinnedVersion = "1.12.22"

// SingBoxTarballSHA256: SHA-256 of official SagerNet release tarballs for SingBoxPinnedVersion.
// Key = linux-<arch> as in asset name. Recompute on pin bump.
var SingBoxTarballSHA256 = map[string]string{
	"linux-amd64":   "50a70a1b71064a7d8ef63737fbef2aa36c991d8dc1c54598b9513c2a15e25e9f",
	"linux-arm64":   "95a9c143e6488584868fc5c03d809c88519c6af0d4ca4cb1fa8a49cc397ae992",
	"linux-armv7":   "a3069ef349f0e635c683122f2d3e9b14f7ee174774ce185495f860e662b483ab",
	"linux-mipsle":  "d8916dbd12405234cc142802ef5315a0e2a58cde43b560d33a815ce2567649d6",
	"linux-riscv64": "41ff0a8871343e598c57a075d74afd456dd6d7c007646c02782e4412dbe5a756",
}

// SingBoxSHA returns expected tarball hash for release arch (amd64, arm64, armv7, mipsle, …).
func SingBoxSHA(linuxArch string) string {
	return SingBoxTarballSHA256["linux-"+linuxArch]
}

// MatchSHA reports case-insensitive equality of hex digests.
func MatchSHA(got, want string) bool {
	return strings.EqualFold(strings.TrimSpace(got), strings.TrimSpace(want))
}
